INSERT INTO dim_producto (producto_key, codigo_producto, nombre_producto, linea_producto, descripcion_linea, escala, proveedor, precio_compra, precio_msrp, presente_en_ventas, presente_en_servicio, lote_carga_key) VALUES
    (15, 'S12_4473', '1957 Chevy Pickup', 'Trucks and Buses', 'The Truck and Bus models are realistic replicas of buses and specialized trucks produced from the early 1920s to present. The models range in size from 1:12 to 1:50 scale and include numerous limited edition and several out-of-production vehicles. Materials used include tin, diecast and plastic. All models include a certificate of authenticity from their manufacturers and are a perfect ornament for the home and office.', '1:12', 'Exoto Designs', '55.70', '118.50', TRUE, TRUE, 8),
    (79, 'S24_3949', 'Corsair F4U ( Bird Cage)', 'Planes', 'Unique, diecast airplane and helicopter replicas suitable for collections, as well as home, office or classroom decorations. Models contain stunning details such as official logos and insignias, rotating jet engines and propellers, retractable wheels, and so on. Most come fully assembled and with a certificate of authenticity from their manufacturers.', '1:24', 'Second Gear Diecast', '29.34', '68.24', TRUE, TRUE, 8),
