-- ---- datawarehouse/edw/star_schema.sql ----
-- ============================================================
-- Data warehouse - dimensional model (fact constellation)
--
-- Two fact tables sharing conformed dimensions:
--
--   fact_ventas             grain: one order line
--   fact_llamadas_servicio  grain: one call to the service center
--
-- Conformed dimensions (used by both facts): dim_tiempo, dim_cliente,
-- dim_producto. Customers and products share the same business key in
-- both sources, which is what allows the two facts to be combined.
--
-- dim_lote_carga is the audit dimension: every dimension and fact row
-- carries the key of the load that last wrote it.
--
-- This is the EDW: the target of layer 7 (Load) of the pipeline in
-- pipeline/. The pipeline works in its own database (staging); only
-- its Load writes here. The data-mart views built on top of the EDW
-- are in datawarehouse/data_marts/data_marts.sql, and the special
-- members (Desconocido, Sin asignar) in special_members.sql.
-- ============================================================

-- The pipeline staging area used to be a schema of this database; it now
-- lives in its own database (staging). Remove the old copy so dw holds
-- only the warehouse.


-- ------------------------------------------------------------
-- Audit dimension: one row per load that reached the warehouse.
--
-- Layer 7 writes it in the same transaction as the data, so the
-- warehouse itself knows which pipeline run and which staging run each
-- row came from. It is what the fact process checks before loading
-- (the dimensions must come from the same staging run as the facts),
-- so the check stays right when the warehouse is rebuilt or restored
-- from a backup. The key is the run_id of the load in the staging
-- database (staging_dw.etl_run).
--
-- The facts reference it with a foreign key, as any dimension. The
-- dimensions carry lote_carga_key as a plain audit column, with no
-- foreign key, so the model stays a star and not a snowflake. Rows
-- written outside the pipeline, like the special members, have no load
-- and carry NULL.
-- ------------------------------------------------------------
CREATE TABLE dim_lote_carga (
    lote_carga_key  INTEGER     PRIMARY KEY,   -- staging_dw.etl_run.run_id of the load
    proceso         VARCHAR(20) NOT NULL,      -- 'dimensiones' | 'hechos'
    run_staging     INTEGER     NOT NULL,      -- staging run the load read
    cargado_en      TIMESTAMP   NOT NULL DEFAULT now(),
    filas           INTEGER     NOT NULL,
    CHECK (proceso IN ('dimensiones', 'hechos'))
);

-- ------------------------------------------------------------
-- Conformed dimensions
-- ------------------------------------------------------------

-- Generated by the ETL, not extracted. The surrogate key is the date
-- as YYYYMMDD.
CREATE TABLE dim_tiempo (
    tiempo_key      INTEGER PRIMARY KEY,
    fecha           DATE        NOT NULL UNIQUE,
    anio            SMALLINT    NOT NULL,
    trimestre       SMALLINT    NOT NULL,
    mes             SMALLINT    NOT NULL,
    nombre_mes      VARCHAR(12) NOT NULL,
    dia             SMALLINT    NOT NULL,
    dia_semana      SMALLINT    NOT NULL,   -- 1 = Monday, 7 = Sunday
    nombre_dia      VARCHAR(12) NOT NULL,
    es_fin_semana   BOOLEAN     NOT NULL,
    anio_mes        CHAR(7)     NOT NULL,   -- '2003-01', monthly grouping key
    lote_carga_key  INTEGER   -- audit: load that last wrote the row
);

-- Customer, conformed across both sources. direccion_completa merges
-- addressLine1 and addressLine2 (the latter is null in 81.97% of rows).
CREATE TABLE dim_cliente (
    cliente_key             SERIAL PRIMARY KEY,
    numero_cliente          INTEGER NOT NULL UNIQUE,   -- business key
    nombre_cliente          VARCHAR(100),
    contacto_nombre         VARCHAR(100),
    contacto_apellido       VARCHAR(100),
    telefono                VARCHAR(50),
    direccion_completa      VARCHAR(220),
    ciudad                  VARCHAR(100),
    estado_region           VARCHAR(100),
    codigo_postal           VARCHAR(20),
    pais                    VARCHAR(100),
    limite_credito          NUMERIC(12,2),
    presente_en_ventas      BOOLEAN NOT NULL DEFAULT FALSE,
    presente_en_servicio    BOOLEAN NOT NULL DEFAULT FALSE,
    lote_carga_key          INTEGER    -- audit: load that last wrote the row
);

-- Product, conformed across both sources, with its product line
-- denormalised from productlines. Only textDescription is kept:
-- htmlDescription and image are 100% null in the source.
CREATE TABLE dim_producto (
    producto_key            SERIAL PRIMARY KEY,
    codigo_producto         VARCHAR(20) NOT NULL UNIQUE,   -- business key
    nombre_producto         VARCHAR(140),
    linea_producto          VARCHAR(60),
    descripcion_linea       TEXT,
    escala                  VARCHAR(20),
    proveedor               VARCHAR(100),
    precio_compra           NUMERIC(12,2),
    precio_msrp             NUMERIC(12,2),
    presente_en_ventas      BOOLEAN NOT NULL DEFAULT FALSE,
    presente_en_servicio    BOOLEAN NOT NULL DEFAULT FALSE,
    lote_carga_key          INTEGER    -- audit: load that last wrote the row
);

-- ------------------------------------------------------------
-- Non-conformed dimension
--
-- Sales reps (classicmodels.employees, 23 rows) and call-center agents
-- (customerservice.cs_employees, 30 rows) are different people with no
-- shared key. Both populations live in one dimension under the
-- composite business key (numero_empleado, sistema_origen).
-- ------------------------------------------------------------
CREATE TABLE dim_empleado (
    empleado_key        SERIAL PRIMARY KEY,
    numero_empleado     INTEGER     NOT NULL,
    sistema_origen      VARCHAR(20) NOT NULL,   -- 'classicmodels' | 'customerservice'
    nombre              VARCHAR(100),
    apellido            VARCHAR(100),
    email               VARCHAR(140),
    cargo               VARCHAR(80),
    numero_oficina      VARCHAR(20),
    lote_carga_key      INTEGER,   -- audit: load that last wrote the row
    UNIQUE (numero_empleado, sistema_origen)
);

-- ------------------------------------------------------------
-- Dimensions that only exist in classicmodels
-- ------------------------------------------------------------

CREATE TABLE dim_oficina (
    oficina_key     SERIAL PRIMARY KEY,
    codigo_oficina  VARCHAR(20) NOT NULL UNIQUE,
    ciudad          VARCHAR(100),
    pais            VARCHAR(100),
    region          VARCHAR(100),
    territorio      VARCHAR(20),
    lote_carga_key  INTEGER   -- audit: load that last wrote the row
);

-- es_efectiva is FALSE for Cancelled, Disputed and On Hold, so reports
-- can exclude those orders without removing them from the warehouse.
CREATE TABLE dim_estado_orden (
    estado_key      SERIAL PRIMARY KEY,
    estado          VARCHAR(30) NOT NULL UNIQUE,
    es_efectiva     BOOLEAN     NOT NULL,
    lote_carga_key  INTEGER   -- audit: load that last wrote the row
);

-- ------------------------------------------------------------
-- fact_ventas - grain: one order line.
-- Fed by orderdetails, orders, products, customers and employees
-- (classicmodels).
-- ------------------------------------------------------------
CREATE TABLE fact_ventas (
    venta_key           BIGSERIAL PRIMARY KEY,

    -- Dimension keys
    tiempo_key          INTEGER NOT NULL REFERENCES dim_tiempo(tiempo_key),
    cliente_key         INTEGER NOT NULL REFERENCES dim_cliente(cliente_key),
    producto_key        INTEGER NOT NULL REFERENCES dim_producto(producto_key),
    -- No key is NULL: a sale without a resolved sales rep points to the
    -- special members of dim_empleado and dim_oficina (special_members.sql).
    empleado_key        INTEGER NOT NULL REFERENCES dim_empleado(empleado_key),
    oficina_key         INTEGER NOT NULL REFERENCES dim_oficina(oficina_key),
    estado_key          INTEGER NOT NULL REFERENCES dim_estado_orden(estado_key),

    -- Degenerate dimensions (source identifiers).
    numero_orden        INTEGER  NOT NULL,
    numero_linea        SMALLINT NOT NULL,

    -- Measures
    cantidad_ordenada   INTEGER       NOT NULL,   -- additive
    precio_unitario     NUMERIC(12,2) NOT NULL,   -- non-additive (average it)
    monto_linea         NUMERIC(14,2) NOT NULL,   -- additive: quantity * price
    costo_linea         NUMERIC(14,2),            -- additive: quantity * buy price
    margen_linea        NUMERIC(14,2),            -- additive: amount - cost
    precio_msrp         NUMERIC(12,2),            -- non-additive
    dias_hasta_envio    SMALLINT,                 -- semi-additive; NULL if not shipped

    lote_carga_key      INTEGER NOT NULL REFERENCES dim_lote_carga(lote_carga_key),

    UNIQUE (numero_orden, numero_linea)
);

-- ------------------------------------------------------------
-- fact_llamadas_servicio - grain: one service call.
-- Fed by cs_customer_calls (customerservice).
-- ------------------------------------------------------------
CREATE TABLE fact_llamadas_servicio (
    llamada_key         BIGSERIAL PRIMARY KEY,

    tiempo_key          INTEGER NOT NULL REFERENCES dim_tiempo(tiempo_key),
    cliente_key         INTEGER NOT NULL REFERENCES dim_cliente(cliente_key),
    producto_key        INTEGER NOT NULL REFERENCES dim_producto(producto_key),
    empleado_key        INTEGER NOT NULL REFERENCES dim_empleado(empleado_key),

    texto_llamada       TEXT,                     -- degenerate dimension

    cantidad_llamadas   SMALLINT NOT NULL DEFAULT 1,   -- additive
    longitud_texto      INTEGER,                       -- additive

    lote_carga_key      INTEGER NOT NULL REFERENCES dim_lote_carga(lote_carga_key)
);

-- ------------------------------------------------------------
-- Foreign-key indexes (PostgreSQL does not create them automatically).
-- ------------------------------------------------------------
CREATE INDEX idx_fv_tiempo   ON fact_ventas(tiempo_key);
CREATE INDEX idx_fv_cliente  ON fact_ventas(cliente_key);
CREATE INDEX idx_fv_producto ON fact_ventas(producto_key);
CREATE INDEX idx_fv_empleado ON fact_ventas(empleado_key);
CREATE INDEX idx_fv_oficina  ON fact_ventas(oficina_key);
CREATE INDEX idx_fv_estado   ON fact_ventas(estado_key);

CREATE INDEX idx_fl_tiempo   ON fact_llamadas_servicio(tiempo_key);
CREATE INDEX idx_fl_cliente  ON fact_llamadas_servicio(cliente_key);
CREATE INDEX idx_fl_producto ON fact_llamadas_servicio(producto_key);
CREATE INDEX idx_fl_empleado ON fact_llamadas_servicio(empleado_key);
CREATE INDEX idx_fv_lote     ON fact_ventas(lote_carga_key);
CREATE INDEX idx_fl_lote     ON fact_llamadas_servicio(lote_carga_key);

-- ---- datawarehouse/data_marts/data_marts.sql ----
-- ============================================================
-- Data marts (schema dm)
--
-- Views built on top of the star schema in public. Each one raises
-- the grain and keeps a single subject:
--
--   dm.vw_interaccion_cliente_producto  effective sales and service
--                                       calls per customer x product x
--                                       month
--   dm.vw_ventas_mensuales_linea        effective sales per month x
--                                       product line
--
-- Both count only effective orders (dim_estado_orden.es_efectiva excludes
-- Cancelled, Disputed and On Hold): units of a cancelled order were
-- never sold.
--
-- Run after datawarehouse/edw/star_schema.sql.
-- ============================================================

CREATE SCHEMA IF NOT EXISTS dm;


-- ------------------------------------------------------------
-- Sales and service per customer x product x month.
--
-- Aggregates both facts to the same grain and joins them with a FULL
-- OUTER JOIN, so it answers which products generate the most service
-- calls per unit sold. Sales are effective orders only; every call
-- counts.
-- ------------------------------------------------------------
CREATE VIEW dm.vw_interaccion_cliente_producto AS
WITH ventas AS (
    SELECT f.cliente_key, f.producto_key, t.anio_mes,
           SUM(f.cantidad_ordenada) AS unidades_vendidas,
           SUM(f.monto_linea)       AS monto_vendido,
           SUM(f.margen_linea)      AS margen_total,
           COUNT(*)                 AS lineas_orden
    FROM public.fact_ventas f
    JOIN public.dim_tiempo       t ON f.tiempo_key = t.tiempo_key
    JOIN public.dim_estado_orden e ON f.estado_key = e.estado_key
    WHERE e.es_efectiva
    GROUP BY 1, 2, 3
),
llamadas AS (
    SELECT l.cliente_key, l.producto_key, t.anio_mes,
           SUM(l.cantidad_llamadas) AS num_llamadas
    FROM public.fact_llamadas_servicio l
    JOIN public.dim_tiempo t ON l.tiempo_key = t.tiempo_key
    GROUP BY 1, 2, 3
)
SELECT
    COALESCE(v.anio_mes, ll.anio_mes) AS anio_mes,
    c.numero_cliente, c.nombre_cliente, c.pais,
    p.codigo_producto, p.nombre_producto, p.linea_producto,
    COALESCE(v.unidades_vendidas, 0) AS unidades_vendidas,
    COALESCE(v.monto_vendido,     0) AS monto_vendido,
    COALESCE(v.margen_total,      0) AS margen_total,
    COALESCE(v.lineas_orden,      0) AS lineas_orden,
    COALESCE(ll.num_llamadas,     0) AS num_llamadas,
    CASE WHEN COALESCE(v.unidades_vendidas, 0) > 0
         THEN ROUND(COALESCE(ll.num_llamadas, 0)::numeric
                    / v.unidades_vendidas, 4)
    END AS llamadas_por_unidad
FROM ventas v
FULL OUTER JOIN llamadas ll
     ON v.cliente_key  = ll.cliente_key
    AND v.producto_key = ll.producto_key
    AND v.anio_mes     = ll.anio_mes
JOIN public.dim_cliente  c ON c.cliente_key  = COALESCE(v.cliente_key,  ll.cliente_key)
JOIN public.dim_producto p ON p.producto_key = COALESCE(v.producto_key, ll.producto_key);

-- ------------------------------------------------------------
-- Monthly sales performance per product line. Effective orders only
-- (dim_estado_orden.es_efectiva excludes Cancelled, Disputed, On Hold).
-- ------------------------------------------------------------
CREATE VIEW dm.vw_ventas_mensuales_linea AS
SELECT t.anio,
       t.trimestre,
       t.anio_mes,
       p.linea_producto,
       COUNT(DISTINCT f.numero_orden)   AS ordenes,
       SUM(f.cantidad_ordenada)         AS unidades,
       ROUND(SUM(f.monto_linea),  2)    AS monto_vendido,
       ROUND(SUM(f.margen_linea), 2)    AS margen,
       ROUND(100 * SUM(f.margen_linea) / NULLIF(SUM(f.monto_linea), 0), 2)
                                        AS margen_pct
FROM public.fact_ventas f
JOIN public.dim_tiempo       t ON f.tiempo_key   = t.tiempo_key
JOIN public.dim_producto     p ON f.producto_key = p.producto_key
JOIN public.dim_estado_orden e ON f.estado_key   = e.estado_key
WHERE e.es_efectiva
GROUP BY t.anio, t.trimestre, t.anio_mes, p.linea_producto;

